import bpy,json,os,math
from mathutils import Vector
from bpy_extras.object_utils import world_to_camera_view
P=os.path.dirname(os.path.abspath(__file__));ROOT=os.path.dirname(P);bpy.ops.wm.open_mainfile(filepath=ROOT+'/scene/hybrid_scene.blend',use_scripts=False);s=bpy.context.scene;c=s.camera;s.render.resolution_x=1672;s.render.resolution_y=941;s.render.resolution_percentage=100;q=c.matrix_world.to_quaternion();right=q@Vector((1,0,0));up=q@Vector((0,1,0));forward=q@Vector((0,0,-1));frame=c.data.view_frame(scene=s);left=min(v.x/-v.z for v in frame);rt=max(v.x/-v.z for v in frame);bottom=min(v.y/-v.z for v in frame);top=max(v.y/-v.z for v in frame)
r={'convention':'Blender world RH Z-up; camera forward is a direction, not lookAt target; screen normalized origin top-left, x right, y down','engine_map':'(x,y,z)->(x,z,-y) on positions and all three basis vectors','position':list(c.matrix_world.translation),'right':list(right),'up':list(up),'forward':list(forward),'worldMatrixRows':[list(x) for x in c.matrix_world],'viewMatrixRows':[list(x) for x in c.matrix_world.inverted()],'projection':'perspective','lens_mm':c.data.lens,'sensor_width_mm':c.data.sensor_width,'sensor_height_mm':c.data.sensor_height,'sensor_fit':c.data.sensor_fit,'shift_x':c.data.shift_x,'shift_y':c.data.shift_y,'pixel_aspect':[s.render.pixel_aspect_x,s.render.pixel_aspect_y],'resolution':[1672,941],'frustumSlopes':{'left':left,'right':rt,'bottom':bottom,'top':top},'fov_y_degrees':math.degrees(math.atan(top)-math.atan(bottom)),'fov_x_degrees':math.degrees(math.atan(rt)-math.atan(left)),'near_suggested':.1,'far_suggested':200,'tests':[]}
for a in json.load(open(ROOT+'/semantic_anchors.json'))['interactions']:
 p=Vector(a['world_blender_z_up']);v=world_to_camera_view(s,c,p);d=p-c.matrix_world.translation;z=d.dot(forward);u=(d.dot(right)/z-left)/(rt-left);y=1-(d.dot(up)/z-bottom)/(top-bottom)
 r['tests'].append({'id':a['id'],'world':list(p),'expectedScreenTopLeft':[v.x,1-v.y],'pureMathScreenTopLeft':[u,y],'forwardDepth':z,'maxError':max(abs(u-v.x),abs(y-(1-v.y)))})
